changeSet.sql:
DO $$
DECLARE
    batch_size INT := 1000;
    offset_val INT := 0;
    rows_updated INT;
BEGIN
    LOOP
        UPDATE orders
        SET priority = CASE
            WHEN total > 500 THEN 2
            WHEN total > 100 THEN 1
            ELSE 0
        END
        WHERE id IN (
            SELECT id FROM orders
            WHERE priority IS NULL
            ORDER BY id
            LIMIT batch_size
        );

        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        EXIT WHEN rows_updated = 0;

        -- Small pause between batches to reduce I/O pressure
        PERFORM pg_sleep(0.01);
    END LOOP;
END $$;

ALTER TABLE orders
    ADD CONSTRAINT nn_orders_priority
    CHECK (priority IS NOT NULL) NOT VALID;

-- VALIDATE acquires ShareUpdateExclusiveLock (allows reads and writes)
-- instead of the full AccessExclusiveLock of a regular NOT NULL
ALTER TABLE orders VALIDATE CONSTRAINT nn_orders_priority;

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_priority_status
    ON orders(priority, status)
    WHERE priority > 0;

CREATE OR REPLACE FUNCTION sync_url_columns()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
        IF NEW.url_key IS DISTINCT FROM OLD.url_key THEN
            NEW.url_slug = NEW.url_key;
        END IF;
        IF NEW.url_slug IS DISTINCT FROM OLD.url_slug THEN
            NEW.url_key = NEW.url_slug;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_url_columns
    BEFORE INSERT OR UPDATE ON categories
    FOR EACH ROW EXECUTE FUNCTION sync_url_columns();
